// ==========================================
// 2. WEB AUDIO API PROCEDURAL SYNTHESIZER
// ==========================================
class SoundFXManager {
  constructor() {
    this.ctx = null;
    this.isMuted = false;
  }

  init() {
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) {
        this.ctx = new AudioCtx();
      }
    }
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  toggleMute() {
    this.isMuted = !this.isMuted;
    return !this.isMuted;
  }

  playTone(freq, duration, type, gainVal) {
    if (this.isMuted) return;
    this.init();
    if (!this.ctx) return;
    type = type || 'sine';
    gainVal = gainVal || 0.15;

    try {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();

      osc.type = type;
      osc.frequency.setValueAtTime(freq, this.ctx.currentTime);

      gain.gain.setValueAtTime(gainVal, this.ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.0001, this.ctx.currentTime + duration);

      osc.connect(gain);
      gain.connect(this.ctx.destination);

      osc.start();
      osc.stop(this.ctx.currentTime + duration);
    } catch (e) {
      // Audio fallback
    }
  }

  playClick() {
    this.playTone(600, 0.05, 'triangle', 0.1);
  }

  playSelect() {
    this.playTone(523.25, 0.08, 'sine', 0.12);
    setTimeout(() => this.playTone(659.25, 0.12, 'sine', 0.12), 60);
  }

  playAttack(soundType) {
    if (this.isMuted) return;
    this.init();
    if (!this.ctx) return;

    const t = this.ctx.currentTime;
    try {
      if (soundType.indexOf('electric') !== -1) {
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(240, t);
        osc.frequency.exponentialRampToValueAtTime(80, t + 0.35);
        gain.gain.setValueAtTime(0.2, t);
        gain.gain.exponentialRampToValueAtTime(0.001, t + 0.35);
        osc.connect(gain);
        gain.connect(this.ctx.destination);
        osc.start(t);
        osc.stop(t + 0.35);
      } else if (soundType === 'fire') {
        this.playNoise(0.4, 300, 0.2);
      } else if (soundType === 'water') {
        this.playTone(400, 0.25, 'sine', 0.15);
        setTimeout(() => this.playTone(580, 0.2, 'sine', 0.12), 80);
      } else if (soundType === 'solar') {
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(800, t);
        osc.frequency.exponentialRampToValueAtTime(150, t + 0.4);
        gain.gain.setValueAtTime(0.25, t);
        gain.gain.exponentialRampToValueAtTime(0.001, t + 0.4);
        osc.connect(gain);
        gain.connect(this.ctx.destination);
        osc.start(t);
        osc.stop(t + 0.4);
      } else if (soundType === 'whip' || soundType === 'slash') {
        this.playTone(700, 0.1, 'sawtooth', 0.15);
      } else if (soundType.indexOf('ghost') !== -1) {
        this.playTone(320, 0.4, 'triangle', 0.18);
        setTimeout(() => this.playTone(280, 0.4, 'sine', 0.15), 100);
      } else {
        this.playTone(180, 0.2, 'square', 0.15);
      }
    } catch (e) {}
  }

  playNoise(duration, filterFreq, gainVal) {
    if (this.isMuted) return;
    this.init();
    if (!this.ctx) return;
    gainVal = gainVal || 0.15;
    try {
      const bufferSize = this.ctx.sampleRate * duration;
      const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
      const output = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        output[i] = Math.random() * 2 - 1;
      }
      const whiteNoise = this.ctx.createBufferSource();
      whiteNoise.buffer = buffer;

      const filter = this.ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.setValueAtTime(filterFreq, this.ctx.currentTime);

      const gain = this.ctx.createGain();
      gain.gain.setValueAtTime(gainVal, this.ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + duration);

      whiteNoise.connect(filter);
      filter.connect(gain);
      gain.connect(this.ctx.destination);

      whiteNoise.start();
    } catch(e) {}
  }

  playHit() {
    this.playTone(120, 0.18, 'square', 0.2);
    this.playNoise(0.12, 500, 0.2);
  }

  playHeal() {
    const notes = [392, 523.25, 659.25, 783.99];
    notes.forEach((note, i) => {
      setTimeout(() => this.playTone(note, 0.15, 'sine', 0.12), i * 70);
    });
  }

  playVictory() {
    const melody = [
      { f: 523.25, d: 0.12 },
      { f: 523.25, d: 0.12 },
      { f: 523.25, d: 0.12 },
      { f: 523.25, d: 0.25 },
      { f: 415.30, d: 0.25 },
      { f: 466.16, d: 0.25 },
      { f: 523.25, d: 0.35 },
      { f: 466.16, d: 0.15 },
      { f: 523.25, d: 0.6 }
    ];
    let delay = 0;
    melody.forEach(item => {
      setTimeout(() => this.playTone(item.f, item.d, 'triangle', 0.2), delay);
      delay += item.d * 1000 + 40;
    });
  }

  playDefeat() {
    const notes = [440, 415.3, 392, 349.23];
    notes.forEach((n, i) => {
      setTimeout(() => this.playTone(n, 0.35, 'sawtooth', 0.12), i * 220);
    });
  }
}

const SFX = new SoundFXManager();

// ==========================================
// 3. BACKGROUND CANVAS PARTICLES (STADIUM AMBIENCE)
// ==========================================
function initBackgroundCanvas() {
  const canvas = document.getElementById('bg-canvas');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  let width = canvas.width = window.innerWidth;
  let height = canvas.height = window.innerHeight;

  window.addEventListener('resize', () => {
    width = canvas.width = window.innerWidth;
    height = canvas.height = window.innerHeight;
  });

  const particles = [];
  const count = 45;
  for (let i = 0; i < count; i++) {
    particles.push({
      x: Math.random() * width,
      y: Math.random() * height,
      size: Math.random() * 2 + 0.8,
      speedX: (Math.random() - 0.5) * 0.4,
      speedY: -Math.random() * 0.5 - 0.2,
      opacity: Math.random() * 0.5 + 0.2,
      color: Math.random() > 0.4 ? '#ffcb05' : '#38bdf8'
    });
  }

  function render() {
    ctx.clearRect(0, 0, width, height);

    const grad = ctx.createRadialGradient(width / 2, height / 3, 50, width / 2, height / 2, width * 0.8);
    grad.addColorStop(0, 'rgba(18, 28, 52, 0.4)');
    grad.addColorStop(1, 'rgba(10, 14, 23, 0.8)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, width, height);

    particles.forEach(p => {
      p.x += p.speedX;
      p.y += p.speedY;

      if (p.y < 0) {
        p.y = height + 10;
        p.x = Math.random() * width;
      }
      if (p.x < 0) p.x = width;
      if (p.x > width) p.x = 0;

      ctx.save();
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
      ctx.fillStyle = p.color;
      ctx.globalAlpha = p.opacity;
      ctx.shadowBlur = 8;
      ctx.shadowColor = p.color;
      ctx.fill();
      ctx.restore();
    });

    requestAnimationFrame(render);
  }
  render();
}

// ==========================================
// 4. GAME STATE CONTROLLER
// ==========================================
class PokemonGameController {
  constructor() {
    this.playerName = '';
    this.selectedPokemon = null;
    this.playerHp = 0;
    this.oppHp = 0;
    this.isPlayerTurn = true;
    this.potionStock = 1;
    this.isBattleActive = false;
    this.hasStormBadge = false;
    this.roastTypewriterTimer = null;
  }

  init() {
    // Populate realistic trainer images
    document.getElementById('img-harsh-avatar').src = TRAINER_ASSETS.harsh;
    document.getElementById('img-anumita-avatar').src = TRAINER_ASSETS.anumita;
    document.getElementById('img-swathi-avatar').src = TRAINER_ASSETS.swathi;
    document.getElementById('img-harsh-roast').src = TRAINER_ASSETS.harsh;
    document.getElementById('harsh-mini-face').src = TRAINER_ASSETS.harsh;
    document.getElementById('img-harsh-defeat').src = TRAINER_ASSETS.harsh;
    document.getElementById('img-harsh-victory').src = TRAINER_ASSETS.harsh;

    this.renderPokemonRoster();
    this.bindEvents();
    initBackgroundCanvas();
  }

  switchView(viewId) {
    document.querySelectorAll('.game-view').forEach(view => {
      view.classList.remove('view-active');
    });
    const target = document.getElementById(viewId);
    if (target) {
      target.classList.add('view-active');
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    const btnGymMap = document.getElementById('btn-gym-map');
    if (viewId === 'view-intro') {
      btnGymMap.style.display = 'none';
    } else {
      btnGymMap.style.display = 'inline-flex';
    }
  }

  bindEvents() {
    // Sound Toggle
    const btnSound = document.getElementById('btn-sound-toggle');
    const soundIcon = document.getElementById('sound-icon');
    btnSound.addEventListener('click', () => {
      const isSoundOn = SFX.toggleMute();
      soundIcon.textContent = isSoundOn ? '🔊' : '🔇';
      btnSound.querySelector('.btn-text').textContent = isSoundOn ? 'SOUND: ON' : 'SOUND: MUTED';
      if (isSoundOn) SFX.playSelect();
    });

    // Return to Gym Map
    document.getElementById('btn-gym-map').addEventListener('click', () => {
      SFX.playClick();
      if (this.playerName) {
        this.switchView('view-hub');
      } else {
        this.switchView('view-intro');
      }
    });

    // Registration Form Submit
    const regForm = document.getElementById('form-registration');
    regForm.addEventListener('submit', (e) => {
      e.preventDefault();
      this.handleRegistration();
    });

    // Harsh Challenge Button (Round 1)
    document.getElementById('btn-challenge-harsh').addEventListener('click', () => {
      SFX.playSelect();
      this.switchView('view-select');
    });

    // Gym 2 Anumita Inspect (Locked)
    document.getElementById('btn-inspect-anumita').addEventListener('click', () => {
      SFX.playClick();
      this.showLockedModal(
        'ROUND 2: LOCKED',
        'ELITE LEADER ANUMITA',
        TRAINER_ASSETS.anumita,
        'ASTRAL SANCTUARY IS SEALED',
        '"Hmph! Gym Leader Anumita is communing with the psychic cosmos in her Astral Sanctuary! Harsh informed her that ' + (this.playerName || 'challengers') + ' can\'t even tell an Electric type from a toaster! Defeat Harsh\'s Storm Gym first to unlock Level 2!"'
      );
    });

    // Final Boss Swathi Inspect (Locked)
    document.getElementById('btn-inspect-swathi').addEventListener('click', () => {
      SFX.playClick();
      this.showLockedModal(
        'FINAL BOSS: LOCKED',
        'SUPREME CHAMPION SWATHI',
        TRAINER_ASSETS.swathi,
        'THE INDIGO THRONE IS RESERVED',
        '"👑 STOP RIGHT THERE! Supreme Champion Swathi is sitting on the Champion\'s Throne drinking iced boba from her golden trophy cup. She only accepts battles from trainers who conquered BOTH Harsh and Anumita! Do not disturb the Queen!"'
      );
    });

    document.getElementById('btn-close-locked').addEventListener('click', () => {
      SFX.playClick();
      document.getElementById('modal-locked').classList.remove('modal-active');
    });

    // Back to Hub from Pokemon Select
    document.getElementById('btn-back-to-hub').addEventListener('click', () => {
      SFX.playClick();
      this.switchView('view-hub');
    });

    // Roast: Change Pokemon
    document.getElementById('btn-roast-change-poke').addEventListener('click', () => {
      SFX.playClick();
      this.switchView('view-select');
    });

    // Roast: Enter Battle
    document.getElementById('btn-start-battle').addEventListener('click', () => {
      SFX.playSelect();
      this.startBattle();
    });

    // Battle: Moves
    document.getElementById('btn-move-1').addEventListener('click', () => this.handlePlayerMove(0));
    document.getElementById('btn-move-2').addEventListener('click', () => this.handlePlayerMove(1));
    document.getElementById('btn-potion').addEventListener('click', () => this.handleUsePotion());
    document.getElementById('btn-battle-forfeit').addEventListener('click', () => {
      if (confirm('Forfeit battle and flee to Gym Map? Harsh will ruthlessly laugh at you!')) {
        this.handlePlayerFaint();
      }
    });

    // Victory Modals Action Buttons
    document.getElementById('btn-victory-rematch').addEventListener('click', () => {
      document.getElementById('modal-victory').classList.remove('modal-active');
      this.startBattle();
    });
    document.getElementById('btn-victory-switch').addEventListener('click', () => {
      document.getElementById('modal-victory').classList.remove('modal-active');
      this.switchView('view-select');
    });
    document.getElementById('btn-victory-hub').addEventListener('click', () => {
      document.getElementById('modal-victory').classList.remove('modal-active');
      this.switchView('view-hub');
    });

    // Defeat Modals Action Buttons
    document.getElementById('btn-defeat-rematch').addEventListener('click', () => {
      document.getElementById('modal-defeat').classList.remove('modal-active');
      this.startBattle();
    });
    document.getElementById('btn-defeat-switch').addEventListener('click', () => {
      document.getElementById('modal-defeat').classList.remove('modal-active');
      this.switchView('view-select');
    });
    document.getElementById('btn-defeat-hub').addEventListener('click', () => {
      document.getElementById('modal-defeat').classList.remove('modal-active');
      this.switchView('view-hub');
    });
  }

  handleRegistration() {
    const input = document.getElementById('input-trainer-name');
    const val = input.value.trim();
    if (!val) {
      alert('Please enter your Pokémon Trainer Name!');
      input.focus();
      return;
    }
    this.playerName = val;

    // Update Nav
    document.getElementById('nav-player-name').textContent = this.playerName;
    document.getElementById('nav-trainer-status').style.display = 'flex';
    document.getElementById('player-trainer-tag').textContent = 'TRAINER: ' + this.playerName.toUpperCase();

    SFX.playSelect();
    this.switchView('view-hub');
  }

  showLockedModal(badgeText, leaderCaption, portraitSrc, title, desc) {
    document.getElementById('locked-modal-badge').textContent = badgeText;
    document.getElementById('locked-leader-name').textContent = leaderCaption;
    document.getElementById('img-locked-leader').src = portraitSrc;
    document.getElementById('locked-modal-title').textContent = title;
    document.getElementById('locked-modal-desc').textContent = desc;
    document.getElementById('modal-locked').classList.add('modal-active');
  }

  renderPokemonRoster() {
    const container = document.getElementById('pokemon-roster');
    container.innerHTML = '';

    Object.values(POKEMON_ROSTER).forEach(p => {
      const card = document.createElement('div');
      card.className = 'poke-select-card';
      card.style.setProperty('--card-accent', p.cardAccent);
      card.style.setProperty('--card-glow', p.cardGlow);
      card.dataset.pokeId = p.id;

      card.innerHTML = 
        '<div class="poke-card-visual">' +
          '<img src="' + p.artwork + '" alt="' + p.name + '" loading="lazy" onerror="this.src=\'' + p.spriteFront + '\'">' +
        '</div>' +
        '<div class="poke-type-badge ' + p.typeBadgeClass + '">' + p.type + '</div>' +
        '<h3 class="poke-name">' + p.name + '</h3>' +
        '<p class="poke-subtitle">' + p.title + '</p>' +
        '<div class="poke-stats-mini">' +
          '<span>HP: ' + p.maxHp + '</span>' +
          '<span>ATK: ' + p.attack + '</span>' +
          '<span>SPD: ' + p.speed + '</span>' +
        '</div>' +
        '<div class="poke-moves-list">' +
          '<div class="poke-move-tag">' +
            '<span>⚡ ' + p.moves[0].name + '</span>' +
            '<span>PWR ' + p.moves[0].power + '</span>' +
          '</div>' +
          '<div class="poke-move-tag">' +
            '<span>💥 ' + p.moves[1].name + '</span>' +
            '<span>PWR ' + p.moves[1].power + '</span>' +
          '</div>' +
        '</div>' +
        '<button class="btn-primary btn-select-poke">' +
          '<span>SELECT ' + p.name.toUpperCase() + '</span>' +
        '</button>';

      card.addEventListener('click', () => {
        this.selectPokemon(p.id);
      });

      container.appendChild(card);
    });
  }

  selectPokemon(pokemonId) {
    const poke = POKEMON_ROSTER[pokemonId];
    if (!poke) return;
    this.selectedPokemon = poke;
    SFX.playSelect();

    // Prepare Roast Screen
    document.getElementById('roast-player-poke').textContent = poke.name + ' (' + poke.type + ')';
    const roastText = poke.harshRoast(this.playerName || 'Trainer');
    this.typewriteRoast(roastText);

    this.switchView('view-roast');
  }

  typewriteRoast(text) {
    const target = document.getElementById('roast-text-container');
    target.innerHTML = '';
    if (this.roastTypewriterTimer) clearInterval(this.roastTypewriterTimer);

    let idx = 0;
    this.roastTypewriterTimer = setInterval(() => {
      if (idx < text.length) {
        target.textContent += text[idx];
        if (idx % 4 === 0) SFX.playClick();
        idx++;
      } else {
        clearInterval(this.roastTypewriterTimer);
      }
    }, 25);
  }

  // ==========================================
  // BATTLE ENGINE
  // ==========================================
  startBattle() {
    if (!this.selectedPokemon) return;

    this.isBattleActive = true;
    this.isPlayerTurn = true;
    this.potionStock = 1;
    this.playerHp = this.selectedPokemon.maxHp;
    this.oppHp = HARSH_POKEMON.maxHp;

    // Setup Opponent Visuals
    document.getElementById('opp-pokemon-name').textContent = HARSH_POKEMON.name;
    document.getElementById('opp-type-badge').textContent = HARSH_POKEMON.type;
    const oppSprite = document.getElementById('opp-sprite');
    oppSprite.src = HARSH_POKEMON.spriteFront;
    oppSprite.onerror = () => { oppSprite.src = HARSH_POKEMON.artwork; };

    // Setup Player Visuals
    document.getElementById('player-pokemon-name').textContent = this.selectedPokemon.name;
    document.getElementById('player-type-badge').textContent = this.selectedPokemon.type;
    document.getElementById('player-type-badge').className = 'hud-type-badge ' + this.selectedPokemon.typeBadgeClass;
    const playerSprite = document.getElementById('player-sprite');
    playerSprite.src = this.selectedPokemon.spriteBack;
    playerSprite.onerror = () => { playerSprite.src = this.selectedPokemon.artwork; };

    // Setup Moves Buttons
    this.setupMoveButton(1, this.selectedPokemon.moves[0]);
    this.setupMoveButton(2, this.selectedPokemon.moves[1]);

    // Setup Potion
    const potionBtn = document.getElementById('btn-potion');
    potionBtn.disabled = false;
    document.getElementById('potion-stock').textContent = '1 LEFT';

    // Clear logs
    const logFeed = document.getElementById('battle-log-feed');
    logFeed.innerHTML = 
      '<div class="log-entry system-entry">' +
        '⚡ BATTLE START: ' + this.playerName + '\'s ' + this.selectedPokemon.name + ' VS Harsh\'s ' + HARSH_POKEMON.name + '!' +
      '</div>';

    this.updateHpBars();
    this.setTurnIndicator(true);
    this.updateHarshBubble('"Ready to get crushed, ' + this.playerName + '?!"');

    this.switchView('view-battle');
  }

  setupMoveButton(index, move) {
    const btn = document.getElementById('btn-move-' + index);
    document.getElementById('m' + index + '-name').textContent = move.name;
    document.getElementById('m' + index + '-type').textContent = move.type;
    document.getElementById('m' + index + '-pwr').textContent = 'PWR: ' + move.power;
    document.getElementById('m' + index + '-acc').textContent = 'ACC: ' + move.accuracy + '%';
    document.getElementById('m' + index + '-desc').textContent = move.desc;
    btn.disabled = false;
  }

  setTurnIndicator(isPlayer) {
    this.isPlayerTurn = isPlayer;
    const badge = document.getElementById('turn-badge');
    const m1 = document.getElementById('btn-move-1');
    const m2 = document.getElementById('btn-move-2');
    const potion = document.getElementById('btn-potion');

    if (isPlayer) {
      badge.textContent = 'YOUR TURN';
      badge.classList.remove('turn-opp');
      m1.disabled = false;
      m2.disabled = false;
      potion.disabled = this.potionStock <= 0;
    } else {
      badge.textContent = "HARSH'S TURN...";
      badge.classList.add('turn-opp');
      m1.disabled = true;
      m2.disabled = true;
      potion.disabled = true;
    }
  }

  updateHpBars() {
    // Opponent
    const oppPct = Math.max(0, Math.min(100, Math.round((this.oppHp / HARSH_POKEMON.maxHp) * 100)));
    const oppFill = document.getElementById('opp-hp-fill');
    oppFill.style.width = oppPct + '%';
    document.getElementById('opp-hp-values').textContent = Math.max(0, this.oppHp) + ' / ' + HARSH_POKEMON.maxHp;

    oppFill.className = 'hp-bar-fill';
    if (oppPct <= 25) oppFill.classList.add('hp-low');
    else if (oppPct <= 50) oppFill.classList.add('hp-mid');

    // Player
    const playerPct = Math.max(0, Math.min(100, Math.round((this.playerHp / this.selectedPokemon.maxHp) * 100)));
    const playerFill = document.getElementById('player-hp-fill');
    playerFill.style.width = playerPct + '%';
    document.getElementById('player-hp-values').textContent = Math.max(0, this.playerHp) + ' / ' + this.selectedPokemon.maxHp;

    playerFill.className = 'hp-bar-fill';
    if (playerPct <= 25) playerFill.classList.add('hp-low');
    else if (playerPct <= 50) playerFill.classList.add('hp-mid');
  }

  appendLog(text, type) {
    type = type || 'system-entry';
    const logFeed = document.getElementById('battle-log-feed');
    const item = document.createElement('div');
    item.className = 'log-entry ' + type;
    item.innerHTML = text;
    logFeed.appendChild(item);
    logFeed.scrollTop = logFeed.scrollHeight;
  }

  updateHarshBubble(text) {
    document.getElementById('harsh-live-text').textContent = text;
  }

  triggerVFX(fxClass) {
    const layer = document.getElementById('attack-vfx-layer');
    layer.className = 'attack-vfx-layer ' + fxClass;
    setTimeout(() => {
      layer.className = 'attack-vfx-layer';
    }, 600);
  }

  showDamageNumber(targetId, text, isCritical) {
    const floater = document.getElementById(targetId);
    floater.textContent = text;
    floater.style.color = isCritical ? '#fbbf24' : '#ef4444';
    floater.classList.remove('float-anim');
    void floater.offsetWidth; // Trigger reflow
    floater.classList.add('float-anim');
  }

  shakeTarget(elementId) {
    const el = document.getElementById(elementId);
    el.classList.add('sprite-hurt');
    document.getElementById('stadium-stage').classList.add('shake-effect');
    setTimeout(() => {
      el.classList.remove('sprite-hurt');
      document.getElementById('stadium-stage').classList.remove('shake-effect');
    }, 500);
  }

  handlePlayerMove(moveIndex) {
    if (!this.isBattleActive || !this.isPlayerTurn) return;
    this.setTurnIndicator(false);

    const move = this.selectedPokemon.moves[moveIndex];
    SFX.playAttack(move.soundType);
    this.triggerVFX(move.fxClass);

    // Accuracy check
    const roll = Math.random() * 100;
    if (roll > move.accuracy) {
      this.appendLog('❌ ' + this.selectedPokemon.name + '\'s <strong>' + move.name + '</strong> missed! Harsh laughs out loud!', 'player-action');
      this.updateHarshBubble('"Did you grease your fingers, ' + this.playerName + '?! Total miss!"');
      setTimeout(() => this.executeHarshTurn(), 1400);
      return;
    }

    // Damage Calculation
    const isCrit = Math.random() < 0.18;
    const critMult = isCrit ? 1.5 : 1.0;
    const variance = (Math.random() * 8) - 4;
    const damage = Math.max(15, Math.round((move.power * critMult) + variance));

    this.oppHp -= damage;
    SFX.playHit();
    this.shakeTarget('opp-sprite');
    this.showDamageNumber('opp-damage-float', '-' + damage + (isCrit ? ' CRIT!' : ''), isCrit);
    this.updateHpBars();

    this.appendLog(
      '💥 ' + this.selectedPokemon.name + ' used <strong>' + move.name + '</strong>! Dealt <strong>' + damage + ' DMG</strong>' + (isCrit ? ' (CRITICAL HIT!)' : '') + ' to Harsh\'s Luxray.',
      'player-action'
    );

    // Random funny mid-battle roast
    const randomRoast = HARSH_BATTLE_TAUNTS[Math.floor(Math.random() * HARSH_BATTLE_TAUNTS.length)](this.playerName);
    this.updateHarshBubble(randomRoast);

    // Check Victory
    if (this.oppHp <= 0) {
      setTimeout(() => this.handleHarshFaint(), 900);
      return;
    }

    // Pass turn to Harsh
    setTimeout(() => this.executeHarshTurn(), 1400);
  }

  handleUsePotion() {
    if (!this.isBattleActive || !this.isPlayerTurn || this.potionStock <= 0) return;
    this.potionStock--;
    document.getElementById('potion-stock').textContent = '0 LEFT';
    document.getElementById('btn-potion').disabled = true;

    const healAmount = 60;
    this.playerHp = Math.min(this.selectedPokemon.maxHp, this.playerHp + healAmount);
    SFX.playHeal();
    this.updateHpBars();

    this.showDamageNumber('player-damage-float', '+' + healAmount + ' HP', true);
    this.appendLog('🧪 ' + this.playerName + ' used a Potion! Restored <strong>+' + healAmount + ' HP</strong> to ' + this.selectedPokemon.name + '.', 'player-action');
    this.updateHarshBubble('"Taking vitamins already, ' + this.playerName + '?! You\'re still going down!"');

    this.setTurnIndicator(false);
    setTimeout(() => this.executeHarshTurn(), 1400);
  }

  executeHarshTurn() {
    if (!this.isBattleActive) return;

    // Pick one of Harsh's 2 signature moves
    const move = HARSH_POKEMON.moves[Math.floor(Math.random() * HARSH_POKEMON.moves.length)];
    SFX.playAttack(move.soundType);
    this.triggerVFX(move.fxClass);

    // Accuracy Check
    const roll = Math.random() * 100;
    if (roll > move.accuracy) {
      this.appendLog('⚡ Harsh\'s Luxray used <strong>' + move.name + '</strong> but missed! Harsh curses under his breath!', 'opp-action');
      this.updateHarshBubble('"Lag! I swear the stadium WiFi just lagged!"');
      this.setTurnIndicator(true);
      return;
    }

    const isCrit = Math.random() < 0.15;
    const critMult = isCrit ? 1.45 : 1.0;
    const variance = (Math.random() * 6) - 3;
    const damage = Math.max(12, Math.round((move.power * critMult) + variance));

    this.playerHp -= damage;
    SFX.playHit();
    this.shakeTarget('player-sprite');
    this.showDamageNumber('player-damage-float', '-' + damage + (isCrit ? ' CRIT!' : ''), isCrit);
    this.updateHpBars();

    this.appendLog(
      '⚡ Harsh\'s Luxray struck back with <strong>' + move.name + '</strong>! Inflicted <strong>' + damage + ' DMG</strong>' + (isCrit ? ' (CRITICAL!)' : '') + ' on ' + this.selectedPokemon.name + '.',
      'opp-action'
    );

    // Check Defeat
    if (this.playerHp <= 0) {
      setTimeout(() => this.handlePlayerFaint(), 900);
      return;
    }

    // Return turn to player
    this.setTurnIndicator(true);
  }

  handleHarshFaint() {
    this.isBattleActive = false;
    this.hasStormBadge = true;
    SFX.playVictory();

    // Unlock badge visual
    const badgeHarsh = document.getElementById('badge-harsh');
    badgeHarsh.classList.remove('locked');

    // Customize Victory Quote with Player Name as requested
    const speechEl = document.getElementById('victory-harsh-speech');
    speechEl.textContent = '"Uhu... okay, okay, you beat me, ' + this.playerName + '... 🙄 BUT I LITERALLY CREATED THIS GAME FOR YOU TO WIN! You really think you\'re Ash Ketchum now?! Don\'t let it go to your head! Anumita and Swathi would turn your ' + this.selectedPokemon.name + ' into dust anyway!"';

    document.getElementById('modal-victory').classList.add('modal-active');
  }

  handlePlayerFaint() {
    this.isBattleActive = false;
    SFX.playDefeat();

    // Customize Defeat Roast with Player Name as requested
    const speechEl = document.getElementById('defeat-harsh-speech');
    speechEl.textContent = '"HAHAHAHA! ' + this.playerName + ', ARE YOU SERIOUS RIGHT NOW?! 😂 I gave you the strongest moves in the franchise and you STILL managed to lose to my Gym?! My Luxray wasn\'t even using 10% of its battery power! Go back to Pallet Town and study Pokémon 101 from Professor Oak!"';

    document.getElementById('modal-defeat').classList.add('modal-active');
  }
}

// ==========================================
// 5. APPLICATION BOOTSTRAP
// ==========================================
window.addEventListener('DOMContentLoaded', () => {
  const game = new PokemonGameController();
  game.init();
});
